CREATE TABLE IF NOT EXISTS batch_jobs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, name TEXT NOT NULL, source_label TEXT NOT NULL, targets_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_batch_jobs_user_created ON batch_jobs(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS batch_items (batch_id TEXT NOT NULL, task_id TEXT NOT NULL UNIQUE, conversation_id TEXT NOT NULL UNIQUE, row_number INTEGER NOT NULL, sku TEXT NOT NULL, product_name TEXT NOT NULL, last_error TEXT, PRIMARY KEY(batch_id,task_id), UNIQUE(batch_id,sku), FOREIGN KEY(batch_id) REFERENCES batch_jobs(id) ON DELETE CASCADE, FOREIGN KEY(task_id) REFERENCES tasks(id) ON DELETE CASCADE, FOREIGN KEY(conversation_id) REFERENCES agent_conversations(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_batch_items_batch_row ON batch_items(batch_id,row_number);
